276	// ─── Crime Scene Templates ───
277	// Modules register examination point templates per scene type.
278	export interface CrimeSceneTemplate {
279	  points: Omit<ExaminationPoint, 'id' | 'examined'>[];
280	  /** Prose text for NPCs who passively notice this scene. {locationName} is interpolated. */
281	  passiveNoticeText?: string;
282	  /** Module callback: personalize points based on victim/perpetrator context */
283	  personalizePoints?: (points: ExaminationPoint[], ctx: { victim?: Agent; perpetrator?: Agent }) => void;
284	  /** Module callback: generate additional points based on context (e.g. profession clues) */
285	  additionalPoints?: (ctx: { victim?: Agent; perpetrator?: Agent }) => Omit<ExaminationPoint, 'id' | 'examined'>[];
286	}
287	
288	const CRIME_SCENE_TEMPLATES: Map<string, CrimeSceneTemplate> = new Map();
289	
