439	// ─── Interact Post-Hooks ───
440	// Modules register hooks that run after an interact step (e.g., suspect evaluation)
441	export type InteractPostHookFn = (owner: Agent, target: Agent, step: GoalStep, agents: Map<string, Agent>, crimeScenes?: Map<string, CrimeScene[]>) => void;
442	
443	const INTERACT_POST_HOOKS: InteractPostHookFn[] = [];
444	
445	export function registerInteractPostHook(hook: InteractPostHookFn): void {
446	  INTERACT_POST_HOOKS.push(hook);
447	}
