449	// ─── Interaction Result Hooks ───
450	// Modules register hooks that run after a goal-driven interaction completes.
451	// Richer context than InteractPostHooks — includes purpose, eventStore, and event emission.
452	export type InteractionResultHookFn = (ctx: {
453	  initiator: Agent;
454	  target: Agent;
455	  step?: GoalStep;
456	  purpose: string;
457	  eventStore: IEventStore;
458	  onExtraEvent?: (e: WorldEvent) => Promise<void>;
459	}) => Promise<void>;
460	
461	const INTERACTION_RESULT_HOOKS: InteractionResultHookFn[] = [];
462	
463	export function registerInteractionResultHook(hook: InteractionResultHookFn): void {
464	  INTERACTION_RESULT_HOOKS.push(hook);
465	}
466	
467	export function getInteractionResultHooks(): InteractionResultHookFn[] {
468	  return INTERACTION_RESULT_HOOKS;
469	}
