9	export function createCrimeScene(
10	  locationId: string,
11	  sceneType: string,
12	  gameDay: number,
13	  gameMinute: number,
14	  perpetrator?: Agent,
15	  victim?: Agent,
16	  witnesses?: string[],
17	): CrimeScene {
18	  const template = getCrimeSceneTemplate(sceneType);
19	  if (!template) {
20	    throw new Error(`No crime scene template registered for type: ${sceneType}`);
21	  }
22	
23	  const points: ExaminationPoint[] = template.points.map((t) => ({
24	    ...t,
25	    id: crypto.randomUUID(),
26	    examined: false,
27	  }));
28	
29	  // Module-defined personalization — template declares how to customize points
30	  if (template.personalizePoints) {
31	    template.personalizePoints(points, { victim, perpetrator });
32	  }
33	
34	  // Module-defined additional points — template generates extras based on context
35	  if (template.additionalPoints) {
36	    const extras = template.additionalPoints({ victim, perpetrator });
37	    for (const ep of extras) {
38	      points.push({ ...ep, id: crypto.randomUUID(), examined: false });
39	    }
40	  }
41	
42	  // Pre-fill noticedBy with witnesses (they already know)
43	  const noticedBy = new Set<string>();
44	  if (perpetrator) noticedBy.add(perpetrator.profile.id);
45	  if (victim) noticedBy.add(victim.profile.id);
46	  if (witnesses) {
47	    for (const w of witnesses) noticedBy.add(w);
48	  }
49	
50	  return {
51	    id: crypto.randomUUID(),
52	    locationId,
53	    crimeType: sceneType,
54	    points,
55	    gameDay,
56	    gameMinute,
57	    noticedBy,
58	    active: true,
59	    perpetratorId: perpetrator?.profile.id,
